def left_insertion(arr, x):
    """
    :param arr:
    :param x:
    :return:
    """
    if len(arr) == 0:
        return 0
    if len(arr) == 1:
        return 0 if arr[0] < x else 1
    if x < arr[0]:
        return 0
    if x > arr[len(arr) - 1]:
        return len(arr)
    if x == arr[len(arr) - 1]:
        return len(arr) - 1
    if x == arr[len(arr) - 2]:
        return len(arr) - 2
    if x < arr[len(arr) - 2]:
        return left_insertion(arr[len(arr) - 1:], x)
    if x > arr[len(arr) - 2]:
        return left_insertion(arr[:len(arr) - 2], x)
    return len(arr) - 1

