def find_combinations(tup_list):
    """
    Finds all combinations of sums with tuples in the given tuple list.
    """
    # Base case
    if len(tup_list) == 0:
        return []

    # Base case
    if len(tup_list) == 1:
        return [tup_list]

    # Recursive case
    result = []
    for i in range(len(tup_list)):
        for combination in find_combinations(tup_list[:i] + tup_list[i+1:]):
            result.append(tup_list[i] + combination)
    return result

