def is_perfect_square(num):
    if num < 0:
        return False
    if num == 0 or num == 1:
        return True
    low = 0
    high = num
    while low <= high:
        mid = (low + high) // 2
        if mid * mid == num:
            return True
        elif mid * mid > num:
            high = mid - 1
        else:
            low = mid + 1
    return False

